import json,html,math
import pandas as pd
from scipy.stats import spearmanr
from common import DATA,SITE,TICKERS,load_json,read_jsonl
PLANNED='2026-09-20 21:00 UTC'

def fmt(v,pct=False):
    if isinstance(v,str): return v
    if v is None: return 'N/A'
    return f'{100*v:.2f}%' if pct else f'{v:+.2f}'

def series(cache,sid):
    return [(o.get('date'),o.get('value')) for o in cache.get(sid,{}).get('observations',[]) if o.get('value') is not None]

def spark(vals,w=420,h=110):
    vals=[float(v) for v in vals if v is not None and math.isfinite(float(v))][-80:]
    if len(vals)<2: return '<div class="empty">Awaiting source history.</div>'
    lo,hi=min(vals),max(vals);span=(hi-lo) or 1
    pts=[]
    for i,v in enumerate(vals):
        x=7+(w-14)*i/(len(vals)-1);y=7+(h-18)*(hi-v)/span;pts.append(f'{x:.1f},{y:.1f}')
    return f'<svg viewBox="0 0 {w} {h}" aria-hidden="true"><polyline points="{" ".join(pts)}" fill="none" stroke="currentColor" stroke-width="2"/><line x1="7" y1="{h-11}" x2="{w-7}" y2="{h-11}" stroke="#e5e7eb"/></svg>'

def track_charts(rows,metrics):
    wh=metrics.get('weekly_history',[]) or []
    cum=[];x=1.0
    for r in wh:
        x*=1+float(r['ls_return']);cum.append(x-1)
    bydate={r['date']:r for r in rows};published=read_jsonl(DATA/'weekly_signal_log.jsonl');ics=[]
    for sig in published:
        r=bydate.get(sig.get('source_date'));fr=(r.get('forward_returns') or {}).get('5d') if r else None
        if fr and sig.get('sector_scores'):
            q=spearmanr([sig['sector_scores'][t] for t in TICKERS],[fr[t] for t in TICKERS]).statistic
            if math.isfinite(q):ics.append(float(q))
    roll=[sum(ics[max(0,i-11):i+1])/len(ics[max(0,i-11):i+1]) for i in range(len(ics))]
    return cum,roll

def build():
    SITE.mkdir(exist_ok=True);(SITE/'assets').mkdir(exist_ok=True)
    metrics=load_json(DATA/'metrics.json',{}) or {};fobj=load_json(DATA/'factor_scores.json',{}) or {};f=fobj.get('factors',{}) or {};w=load_json(DATA/'weekly_signal.json',{}) or {};memo=load_json(DATA/'memo.json',{}) or {};cache=load_json(DATA/'fred_cache.json',{}) or {};rows=read_jsonl(DATA/'model_log.jsonl')
    live=bool(rows and rows[-1].get('public_live') and w.get('public_live')); dayn=len(rows)
    if live and len(w.get('ow',[]))==3:
        model_panel=f'''<div class="badge">Model v1.0 · Live since {html.escape(str(w.get('published_ts_utc',''))[:10])} · Day {dayn} of tracking</div><div class="alloc"><div><span>Overweight</span><b>{' · '.join(w['ow'])}</b></div><div><span>Neutral</span><b>{' · '.join(w['neutral'])}</b></div><div><span>Underweight</span><b>{' · '.join(w['uw'])}</b></div></div><div class="metrics">{metric_buttons(metrics)}</div>'''
    else:
        model_panel=f'''<div class="spin"><b>Model spinning up</b><p>First live call {PLANNED}. Methodology available now.</p><small>Model v1.0 · Public live OFF · Day {dayn} of shadow tracking</small></div>'''
    factor_info={'growth':{'group':'Growth & demand','formula':'Mean of 5-year rolling z-scores: PAYEMS change, INDPRO YoY, RSAFS YoY.','series':['PAYEMS','INDPRO','RSAFS'],'section':'3'},'inflation':{'group':'Prices & policy','formula':'Mean of 5-year rolling z-scores: CPILFESL YoY, PCEPILFE YoY, T5YIFR level (monthly-aligned).','series':['CPILFESL','PCEPILFE','T5YIFR'],'section':'3'},'rates':{'group':'Prices & policy','formula':'5-year rolling z-score of DGS10 level. Positive means higher rates.','series':['DGS10'],'section':'3'},'credit_stress':{'group':'Financial conditions','formula':'Mean of 5-year rolling z-scores of BAMLH0A0HYM2 and BAMLC0A0CM. Positive means wider spreads.','series':['BAMLH0A0HYM2','BAMLC0A0CM'],'section':'3'},'curve_steep':{'group':'Financial conditions','formula':'5-year rolling z-score of T10Y2Y level. Positive means steeper.','series':['T10Y2Y'],'section':'3'},'external':{'group':'External','formula':'Context only in v1.0. No External factor is scored; model exposure is zero.','series':[],'section':'7'}}
    groups=[('Growth & demand',['growth']),('Prices & policy',['inflation','rates']),('Financial conditions',['credit_stress','curve_steep']),('External',['external'])];heat=''
    for g,ks in groups:
        its=''
        for k in ks:
            value='Context' if k=='external' else fmt(f.get(k));subtitle='Not scored in frozen v1.0' if k=='external' else k.replace('_',' ');its+=f'<button class="tile" data-factor="{k}"><span>{html.escape(g)}</span><b>{value}</b><small>{html.escape(subtitle)}</small></button>'
        heat+=f'<div class="group"><h3>{html.escape(g)}</h3>{its}</div>'
    dashboard_defs={'rates':('Rates & Yield Curve',['DGS10','T10Y2Y'],'DGS10 level and T10Y2Y curve spread; these feed Rates and Curve Steepness.'),'infl':('Inflation',['CPILFESL','PCEPILFE','T5YIFR'],'Core CPI YoY, Core PCE YoY, and 5Y inflation-forward level.'),'labor':('Labor',['PAYEMS'],'PAYEMS monthly change; one-third of the Growth factor.'),'growthtab':('Growth',['INDPRO','RSAFS'],'INDPRO YoY and RSAFS YoY; two-thirds of the Growth factor.'),'fed':('Fed Watch',['DGS10','T5YIFR','T10Y2Y'],'Market rates, forward inflation compensation, and curve slope shown together as policy-sensitive context.')}
    tabs=''.join(f'<button class="subtab {"on" if i==0 else ""}" data-tab="{k}">{v[0]}</button>' for i,(k,v) in enumerate(dashboard_defs.items()));panels=''
    for i,(k,(title,sids,insight)) in enumerate(dashboard_defs.items()):
        minis=''
        for sid in sids:
            obs=series(cache,sid);vals=[v for _,v in obs];latest=obs[-1] if obs else (None,None);minis+=f'''<a class="seriescard" target="_blank" rel="noopener" href="https://fred.stlouisfed.org/series/{sid}"><div><b>{sid}</b><span>{html.escape(str(latest[0] or 'Awaiting data'))}</span></div>{spark(vals)}<strong>{'' if latest[1] is None else f'{float(latest[1]):.2f}'}</strong></a>'''
        panels+=f'''<section id="tab-{k}" class="dashpanel" {'' if i==0 else 'hidden'}><button class="charthead" data-chart="{k}"><h3>{title}</h3><p>{html.escape(insight)}</p><small>Click for formula, FRED series, and methodology.</small></button><div class="minicharts">{minis}</div></section>'''
    css='''*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#111827;font:15px/1.5 Arial,sans-serif}.wrap{max-width:1180px;margin:auto;padding:14px}.hero{background:#0f172a;color:#fff;padding:22px;border-radius:16px}.hero h1{margin:4px 0}.badge{font-size:12px;color:#667085;margin-bottom:8px}.hero .badge{color:#cbd5e1}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:16px;margin-top:12px}.tabs,.subtabs{display:flex;gap:8px;margin:12px 0;flex-wrap:wrap}.tabs button,.tabs a,.subtab{padding:9px 12px;border:1px solid #d0d5dd;border-radius:999px;background:white;color:#111827;text-decoration:none;cursor:pointer}.tabs .on,.subtab.on{background:#111827;color:white}.view[hidden],.dashpanel[hidden]{display:none}.alloc{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.alloc div,.metric,.tile,.seriescard{border:1px solid #e5e7eb;border-radius:10px;padding:12px;background:white;text-align:left}.alloc span,.tile span,.metric span{display:block;font-size:10px;color:#667085;text-transform:uppercase}.alloc b,.tile b,.metric b{display:block;font-size:18px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}.metric,.tile,.charthead{cursor:pointer}.spin{padding:18px;background:#fff7ed;border:1px solid #fed7aa;border-radius:12px}.heat{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.group{border:1px solid #e5e7eb;border-radius:12px;padding:10px}.group h3{font-size:12px;margin:0 0 6px;color:#475467}.group .tile{width:100%;border:0;border-top:1px solid #eef2f6;border-radius:0}.group .tile:first-of-type{border-top:0}.modal{margin-top:10px;padding:12px;border-radius:10px;background:#f8fafc;border:1px solid #e5e7eb}.charthead{width:100%;border:0;background:#fff;text-align:left;padding:0}.charthead h3{margin-bottom:2px}.minicharts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.seriescard{display:block;text-decoration:none;color:#334155;min-width:0}.seriescard div{display:flex;justify-content:space-between;gap:8px}.seriescard span{font-size:11px;color:#667085}.seriescard svg{width:100%;height:95px}.seriescard strong{font-size:18px}.empty{height:95px;display:grid;place-items:center;color:#98a2b3;background:#f8fafc;border-radius:8px}.src a{margin-right:12px}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:8px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top}th button{border:0;background:transparent;font-weight:700;cursor:pointer}.trackcharts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.trackchart{border:1px solid #e5e7eb;border-radius:12px;padding:12px;background:#fff;cursor:pointer;text-align:left}.trackchart svg{width:100%;height:130px}@media(max-width:760px){.alloc,.metrics,.heat,.minicharts,.trackcharts{grid-template-columns:1fr}.wrap{padding:10px}}'''
    data=json.dumps({'factorInfo':factor_info,'chartInfo':{k:{'title':v[0],'series':v[1],'formula':v[2]} for k,v in dashboard_defs.items()},'metricInfo':metric_info()})
    index=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>RGIP Macro Model v1.0</title><style>{css}</style></head><body><div class="wrap"><section class="hero"><div class="badge">Macro Model v1.0 · Public live {'ON' if live else 'OFF'}</div><h1>RGIP Macro Dashboard + Daily Macro Pulse</h1><p>One macro product with a five-minute Pulse and a deeper dashboard view.</p></section><div class="tabs"><button class="on" data-view="pulse">Daily Pulse</button><button data-view="dashboard">RGIP Dashboard</button><a href="model.html">Model drill-down</a></div><main id="pulse" class="view"><section class="card"><h2>Sector rotation model</h2>{model_panel}<div id="metricDetail" class="modal" hidden></div></section><section class="card"><h2>Morning memo</h2><p>{html.escape(memo.get('text','Memo will populate after the first valid production run.'))}</p><small>Generated {html.escape(str(memo.get('generated_ts_utc') or 'not yet'))}</small></section><section class="card"><h2>Signal heatmap</h2><div class="heat">{heat}</div><div id="factorDetail" class="modal" hidden></div></section></main><main id="dashboard" class="view" hidden><section class="card"><h2>RGIP Macro Dashboard</h2><div class="subtabs">{tabs}</div>{panels}<div id="chartDetail" class="modal" hidden></div></section></main><section class="card src"><a href="assets/methodology.pdf">Methodology PDF</a><a href="model.html">Full model log</a><a href="https://github.com/m2hurst-cyber/cryptobet/blob/main/data/model_log.jsonl">Raw log on GitHub</a></section></div><script>const D={data};document.querySelectorAll('.tabs button').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('on'));b.classList.add('on');document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==b.dataset.view)}}));document.querySelectorAll('.subtab').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('.subtab').forEach(x=>x.classList.remove('on'));b.classList.add('on');document.querySelectorAll('.dashpanel').forEach(v=>v.hidden=v.id!==`tab-${{b.dataset.tab}}`)}}));function factor(k){{const o=D.factorInfo[k],box=document.querySelector('#factorDetail');const links=(o.series||[]).map(s=>`<a target="_blank" rel="noopener" href="https://fred.stlouisfed.org/series/${{s}}">${{s}} ↗</a>`).join(' · ')||'No scored FRED series in v1.0.';box.hidden=false;box.innerHTML=`<b>${{o.group}}</b><p>${{o.formula}}</p><p>${{links}}</p><p><a href="assets/methodology.pdf#page=2">Whitepaper definition ↗</a></p>`}}document.querySelectorAll('.tile[data-factor]').forEach(t=>t.addEventListener('click',()=>factor(t.dataset.factor)));document.querySelectorAll('.metric').forEach(t=>t.addEventListener('click',()=>{{const box=document.querySelector('#metricDetail');box.hidden=false;box.innerHTML=`<p>${{D.metricInfo[t.dataset.metric]}}</p><p><a href="assets/methodology.pdf#page=5">Whitepaper metrics ↗</a></p>`}}));document.querySelectorAll('.charthead').forEach(t=>t.addEventListener('click',()=>{{const o=D.chartInfo[t.dataset.chart],box=document.querySelector('#chartDetail');box.hidden=false;box.innerHTML=`<b>${{o.title}}</b><p>${{o.formula}}</p><p>${{o.series.map(s=>`<a target="_blank" rel="noopener" href="https://fred.stlouisfed.org/series/${{s}}">${{s}} ↗</a>`).join(' · ')}}</p><p><a href="assets/methodology.pdf">Whitepaper ↗</a></p>`}}));</script></body></html>'''
    (SITE/'index.html').write_text(index)
    cum,ric=track_charts(rows,metrics);metricbar=f'<div class="metrics">{metric_buttons(metrics)}</div><div id="metricDetail" class="modal" hidden></div>';trs=[]
    for r in rows:
        fr=r.get('forward_returns') or {};trs.append('<tr>'+''.join([f'<td>{html.escape(r.get("date",""))}</td>',f'<td>{html.escape(r.get("run_ts_utc",""))}</td>',f'<td>{html.escape(json.dumps(r.get("factor_scores",{}),separators=(",",":")))}</td>',f'<td>{html.escape(json.dumps(r.get("sector_scores",{}),separators=(",",":")))}</td>',f'<td>{html.escape(", ".join(r.get("ow",[])))}</td>',f'<td>{html.escape(", ".join(r.get("neutral",[])))}</td>',f'<td>{html.escape(", ".join(r.get("uw",[])))}</td>',f'<td>{html.escape(", ".join(r.get("data_quality_flags",[])))}</td>',f'<td>{html.escape(json.dumps(fr,separators=(",",":")))}</td>',f'<td>{"LIVE" if r.get("public_live") else "OFF"}</td>'])+'</tr>')
    body=''.join(trs) or '<tr><td colspan="10">No log rows yet.</td></tr>';mdata=json.dumps({'metricInfo':metric_info()})
    model=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Macro Model v1.0 — Drill-down</title><style>{css}</style></head><body><div class="wrap"><section class="hero"><div class="badge">Model v1.0 · forward-only live experiment</div><h1>Model drill-down</h1><p>Signal fields are append-only and immutable. Forward returns populate only after they become observable.</p></section><section class="card"><h2>Track record</h2>{metricbar}</section><section class="card"><h2>Track-record charts</h2><div class="trackcharts"><button class="trackchart" data-metric="ls"><h3>Cumulative OW − UW return</h3>{spark(cum,520,140)}<b>{fmt(metrics.get('long_short_cumulative_return'),True)}</b></button><button class="trackchart" data-metric="ic"><h3>Rolling 12-week Information Coefficient</h3>{spark(ric,520,140)}<b>{fmt(metrics.get('ic_12w'))}</b></button></div></section><section class="card"><h2>Full historical model log</h2><div class="tablewrap"><table id="log"><thead><tr>{''.join(f'<th><button data-col="{i}">{x} ↕</button></th>' for i,x in enumerate(['Date','Run UTC','Factors','Sector scores','OW','Neutral','UW','Flags','Forward returns','Public']))}</tr></thead><tbody>{body}</tbody></table></div></section><section class="card src"><a href="assets/methodology.pdf">Methodology PDF</a><a href="https://github.com/m2hurst-cyber/cryptobet/blob/main/data/model_log.jsonl">Raw log on GitHub</a><a href="index.html">Dashboard</a></section></div><script>const D={mdata};let sortDir={{}};document.querySelectorAll('#log th button').forEach(b=>b.addEventListener('click',()=>{{const c=+b.dataset.col,d=sortDir[c]=-(sortDir[c]||-1),tb=document.querySelector('#log tbody'),rs=[...tb.rows];rs.sort((a,z)=>d*a.cells[c].innerText.localeCompare(z.cells[c].innerText,undefined,{{numeric:true}}));rs.forEach(r=>tb.appendChild(r))}}));document.querySelectorAll('.metric,.trackchart').forEach(t=>t.addEventListener('click',()=>{{const box=document.querySelector('#metricDetail');box.hidden=false;box.innerHTML=`<p>${{D.metricInfo[t.dataset.metric]}}</p><p><a href="assets/methodology.pdf#page=5">Whitepaper metrics ↗</a></p>`}}));</script></body></html>'''
    (SITE/'model.html').write_text(model);return {'index':str(SITE/'index.html'),'model':str(SITE/'model.html')}

def metric_info(): return {'hit':'Weekly hit rate = share of eligible weeks where the equal-weight OW basket beats the equal-weight UW basket; hidden until 8 weekly observations.','ls':'Long-short cumulative return = product of one plus weekly OW-minus-UW return, less one.','ic':'Information Coefficient = Spearman rank correlation between weekly sector scores and 5-trading-day forward returns; hidden until 12 eligible weeks.','turn':'Turnover = new OW names / 3 plus new UW names / 3, averaged; hidden until 4 weekly observations.'}
def metric_buttons(m): return ''.join([f'<button class="metric" data-metric="hit"><span>Hit rate</span><b>{fmt(m.get("hit_rate"),True)}</b></button>',f'<button class="metric" data-metric="ls"><span>Long-short</span><b>{fmt(m.get("long_short_cumulative_return"),True)}</b></button>',f'<button class="metric" data-metric="ic"><span>IC (12w)</span><b>{fmt(m.get("ic_12w"))}</b></button>',f'<button class="metric" data-metric="turn"><span>Turnover</span><b>{fmt(m.get("turnover"),True)}</b></button>'])
if __name__=='__main__': print(json.dumps(build(),indent=2))
